old_data = json.loads(old_json_str)

# Extract unique categories
category_names = []
for link in old_data.get('links', []):
    cat = link.get('category')
    if cat and cat not in category_names:
        category_names.append(cat)

# Create categories dictionary
categories = []
category_map = {}
for i, name in enumerate(category_names, 1):
    categories.append({"id": i, "name": name})
    category_map[name] = i

# Convert links
new_links = []
for i, old_link in enumerate(old_data.get('links', []), 1):
    new_link = {
        "id": i, # generate brand new sequential integer IDs
        "title": old_link.get("title", "Untitled"),
        "url": old_link.get("url", ""),
        "createdAt": old_link.get("createdAt", datetime.datetime.now().isoformat()),
        "categoryId": category_map.get(old_link.get("category")),
        "isPinned": 1 if old_link.get("isPinned") else 0, # Database uses integers 0/1 or booleans? 
        "isFavorite": 1 if old_link.get("isFavorite") else 0,
        "isLocked": 1 if old_link.get("isLocked") else 0
    }
    # Wait, our database uses booleans in JSON export!
    # Let me fix that.
    new_link["isPinned"] = old_link.get("isPinned", False)
    new_link["isFavorite"] = old_link.get("isFavorite", False)
    new_link["isLocked"] = old_link.get("isLocked", False)
    new_links.append(new_link)

# New Data Structure
new_data = {
    "version": 1,
    "exportedAt": datetime.datetime.now().isoformat(),
    "categories": categories,
    "links": new_links
}

with open('converted_backup.json', 'w', encoding='utf-8') as f:
    json.dump(new_data, f, indent=2)

print("Saved to converted_backup.json")
